<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Hulu</title>
<style>
  *{box-sizing:border-box}
  html,body{margin:0;padding:0;background:#08090b;color:#fff;font-family:Arial,Helvetica,sans-serif}
  body{font-size:16px}
  .btn{cursor:pointer}
  section{position:relative}
  .hero{
    height:610px;
    min-height:610px;
    background:
      linear-gradient(rgba(0,0,0,.48),rgba(0,0,0,.7)),
      url("__PLACEHOLDER_ASSETS_BASE_DIR__/026.jpg") center top/cover no-repeat;
    text-align:center;
    padding-top:42px;
  }
  .hero h1{font-size:38px;margin:0 0 16px;font-weight:700}
  .hero h3{font-size:21px;margin:0 0 28px}
  .hero-grid{width:680px;margin:auto;display:flex;justify-content:center;gap:14px}
  .offer{width:330px;min-height:285px;padding:8px 16px}
  .offer-label{font-size:11px;color:#20f58e;font-weight:bold;margin-bottom:17px}
  .brands{height:46px;display:flex;align-items:center;justify-content:center;gap:12px;font-size:25px;font-weight:bold}
  .disney{font-family:Georgia,serif;font-style:italic;font-size:24px}
  .hulu{color:#12f083;font-size:28px}
  .espn{color:#ef3d32;font-size:18px;font-style:italic}
  .offer p{font-size:18px;line-height:1.18;font-weight:bold;margin:25px 0 18px}
  .green-btn{
    background:#18f486;color:#001b0e;border:0;border-radius:3px;
    width:100%;height:42px;font-size:12px;font-weight:bold
  }
  .offer a,.terms{display:block;color:#fff;text-decoration:underline;font-size:11px;margin-top:14px}
  .bundle-bar{
    height:132px;background:#0b4d59;display:flex;align-items:center;justify-content:center;
    gap:100px;padding:0 60px
  }
  .bundle-bar .brands{width:230px;font-size:16px}
  .bundle-copy{width:630px;text-align:left}
  .bundle-copy .tiny{color:#19f58d;font-size:10px;font-weight:bold}
  .bundle-copy p{font-size:20px;line-height:1.25;margin:10px 0 0}
  .bundle-bar .green-btn{width:145px}
  .dark-section{background:#08090b}
  .tv-love{height:670px;text-align:center;padding-top:68px}
  .eyebrow{color:#16f18a;font-size:12px;font-weight:bold;letter-spacing:.3px}
  h2{font-size:38px;margin:17px 0 24px}
  .intro{width:700px;max-width:90%;margin:0 auto;font-size:17px;line-height:1.35}
  .cards{display:flex;justify-content:center;gap:36px;margin-top:58px}
  .card{width:290px;height:470px;position:relative;border-radius:7px;overflow:hidden;background:#111;text-align:left}
  .card img{width:100%;height:100%;object-fit:cover;display:block}
  .card:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.12),rgba(0,0,0,.28))}
  .card-title{position:absolute;z-index:2;top:23px;left:18px;font-size:16px;font-weight:bold}
  .card-title strong{display:block;font-size:22px;margin-top:8px}
  .live-section{height:610px;text-align:center;padding-top:75px}
  .live-section h2{margin-top:18px}
  .live-section .intro{width:750px}
  .trial{margin-top:25px;width:230px}
  .fine{font-size:9px;color:#aaa;width:830px;max-width:90%;margin:15px auto 0;line-height:1.2}
  .channels{display:block;color:#ddd;text-decoration:underline;font-size:14px;font-weight:bold;margin-top:28px}
  .sports{
    height:620px;
    background:
      linear-gradient(90deg,rgba(0,75,41,.78),rgba(0,80,43,.38)),
      url("__PLACEHOLDER_ASSETS_BASE_DIR__/036.jpg") center/cover no-repeat;
    padding:80px 0 0 calc(50% - 625px);
  }
  .sports-copy{width:450px}
  .tabs{display:flex;gap:36px;font-size:12px;font-weight:bold;color:#b8c9be;margin-bottom:30px}
  .tabs span:first-child{color:white;border-bottom:4px solid white;padding-bottom:15px}
  .sports h2{margin:0 0 18px;font-size:38px}
  .sports p{font-size:17px;line-height:1.35}
  .sports-logos{display:flex;gap:16px;margin-top:20px}
  .sports-logos i{width:40px;height:40px;border-radius:50%;background:#fff;color:#123;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:bold;font-style:normal}
  .screen{
    position:absolute;left:64%;top:165px;width:590px;height:390px;
    background:#071329;border:13px solid #292a2a;box-shadow:0 0 30px #001;
    padding:72px 70px;color:#ddd
  }
  .screen small{letter-spacing:2px}
  .screen h3{font-size:39px;font-weight:normal;line-height:1.25;margin:22px 0}
  .screen p{line-height:1.4;color:#bbb}
  .screen button{padding:14px 35px;border:0;margin-top:18px;font-weight:bold}
  .plans{min-height:1040px;padding:64px 0 30px;text-align:center}
  .plans h2{margin-top:0}
  .plans .intro{font-size:16px}
  select{margin-top:42px;width:225px;height:40px;border-radius:22px;padding:0 20px;background:#fff;border:0;font-weight:bold}
  .plan-cards{display:flex;justify-content:center;gap:14px;margin-top:20px}
  .plan{width:310px;height:195px;padding:35px 0 0;border:1px solid #111820}
  .plan.selected{border-color:#151b21}
  .plan .brands{font-size:16px}
  .plan h4{font-size:12px;margin:18px 0}
  .price{height:48px;background:white;color:#111;margin:0 0 10px;padding:16px;font-weight:bold;font-size:13px}
  .save{font-size:10px;font-weight:bold}
  .compare{width:780px;margin:18px auto 0;text-align:left;border-top:1px solid #444}
  .row{display:grid;grid-template-columns:2fr 1fr 1fr;min-height:58px;border-bottom:1px solid #444;align-items:center;font-size:12px}
  .row>div{padding:10px 3px}
  .row>div:not(:first-child){text-align:center}
  .check{color:#20f58e;font-size:25px}
  .notes{font-size:10px;text-align:left;margin:12px 5px;line-height:1.2}
  .addons{border-top:1px solid #444;border-bottom:1px solid #444;padding:24px;margin-top:48px;font-size:14px}
  footer{height:440px;background:#e9ebf2;color:#69707c;padding:56px calc(50% - 650px) 30px}
  .footer-cols{display:grid;grid-template-columns:1.2fr 1.2fr 1.2fr 1.5fr 1fr;gap:45px}
  footer h5{margin:0 0 10px;color:#626873;font-size:11px}
  footer p{font-size:12px;line-height:1.9;margin:0}
  .footer-bottom{border-top:1px solid #d4d7df;margin-top:75px;padding-top:30px}
  .social{font-size:18px;word-spacing:18px;margin-bottom:28px}
  .legal{font-size:11px;line-height:2}
  @media(max-width:900px){
    .hero-grid,.cards,.plan-cards{flex-wrap:wrap;width:95%}
    .hero{height:auto;padding-bottom:40px}
    .offer{width:45%}
    .bundle-bar{gap:20px}
    .sports{padding-left:30px}
    .screen{display:none}
    .compare{width:90%}
    footer{padding:40px 25px}
  }
</style>
</head>
